-- ============================================================================
-- V53__reset_sales_einvoices_seed.sql
--
-- Replaces the local Sales e-Invoices seed (DOC_TYPE='I') with a fresh
-- snapshot from JEX DEV. The previous local Sales seed (V51) carried
-- '1C24TAA-%' / '1C25TAA-%' / '1C25THH-%' rows that no longer match the
-- live data Sonny wants the page to render — they are removed and
-- replaced with the 30 most-recent visible Sales rows from DEV.
--
-- Why this migration
-- ------------------
--   * The V51 Sales seed values were sourced from a snapshot Sonny later
--     marked as incorrect; they don't reflect what the Sales e-Invoices
--     UI should show during testing.
--   * Required for proper Sales UI testing — the page needs realistic,
--     date-recent rows to exercise the date-range picker, pagination,
--     keyword search, and per-currency totals.
--   * The Bill / Expenses seed (V52, DOC_TYPE='B', 30 rows) is unrelated
--     and remains untouched.
--
-- Source
-- ------
-- 30 most-recent visible Sales rows from JEX DEV (`wecmsvndev`) under
-- tenant VN_VNM0004_000001, captured 2026-05-04 via the read-only
-- `postgres` MCP. Filter mirrors the Phase 2 listing baseline (rule
-- IR-2):
--
--     WHERE BIZ_KEY = 'VN_VNM0004_000001'
--       AND DOC_TYPE = 'I'
--       AND PROV_STTS NOT IN ('VD', 'EE')
--       AND HAND_REG_YN <> 'Y'
--     ORDER BY ISSU_DT DESC, REG_DTM DESC
--     LIMIT 30
--
-- All 30 rows belong to the '1C25TWV-%' series and span ISSU_DT
-- 2025-10-15 .. 2025-10-16. Every column is preserved verbatim from
-- DEV — no value modified, no re-keying, no synthetic data. Per the
-- workspace Data Migration Rule (max 30 rows, real DEV data,
-- idempotent seed).
--
-- Scope and safety
-- ----------------
--   * DELETE limited to (BIZ_KEY = 'VN_VNM0004_000001', DOC_TYPE = 'I')
--     — Bill / Expense rows (DOC_TYPE = 'B') and rows in any other
--     tenant are left intact. The local DB has only the single
--     R&D tenant (per `wecms.tenant.biz-key`) so the BIZ_KEY clause
--     is documentation, not scope-narrowing.
--   * INSERT uses `ON CONFLICT (biz_key, doc_id) DO NOTHING` so
--     re-running the migration after a manual `flyway repair` is a
--     no-op — the DELETE wipes the V53 rows, the INSERT re-creates
--     them; if any row was inserted out-of-band with the same
--     (BIZ_KEY, DOC_ID), it survives unchanged.
--   * No FK references this table in the local schema (V24 added FKs
--     OUTBOUND from BUSA_DOC_MSTR; child tables BUSA_DOC_DETL /
--     BUSA_DOC_DETL_HIS / BUSA_DOC_MSTR_HIS are not yet in local
--     Flyway). EINV_FEE_DETL / EINV_TAX_DETL / BUSA_DOC_RCV_PAY_HIS
--     hold rows referencing the previous DOC_IDs but no FK enforces
--     that link locally — they remain in place per the V51 precedent.
--   * Constraint compliance verified before applying:
--       PK    (biz_key, doc_id)               — 30 unique DOC_IDs
--       UK01  (biz_key, reg_dt, seq_no)       — REG_DT NULL on every
--                                               row, PostgreSQL's
--                                               NULLs-distinct
--                                               semantics allow all 30
--       CHK01 doc_type ∈ ('I','B','E')        — every row 'I'
--       CHK02 pay_due_cd ∈ ('15','30','60','00') — every row '30'
--       CHK07 trco_trsc_ccy_cd ∈ ('VND','USD','999','998') or NULL
--                                              — every row 'VND'
-- ============================================================================

-- 1) Wipe the previous Sales seed.
DELETE FROM busa_doc_mstr
WHERE biz_key = 'VN_VNM0004_000001'
  AND doc_type = 'I';

-- 2) Insert fresh DEV Sales rows. Column list mirrors V51 / V52 verbatim
--    so the three seed migrations stay byte-for-byte compatible at the
--    column level.
INSERT INTO busa_doc_mstr (biz_key,user_id,doc_id,issu_tax_id,doc_type,issu_cmnm,issu_cmenm,issu_rppr_nm,issu_rprs_tlph,issu_fxno,issu_bsun_post_adrs,issu_bsun_dtl_adrs,issu_bsun_st,issu_bsun_city,trco_key,trco_tax_id,trco_cmnm,trco_cmenm,trco_rppr_nm,trco_rprs_tlph,trco_fxno,trco_bsun_post_adrs,trco_bsun_dtl_adrs,trco_bsun_st,trco_bsun_city,trco_trsc_ccy_cd,issu_dt,due_dt,pay_due_cd,busa_usag_cd,totl_amt,sply_amt_sum,tax_amt_sum,prjt_no,trsc_msg,prov_stts,eml_trf_dtm,org_file_nm,save_file_nm,file_size,cont,use_dt,user_nm,appr_seq_no,reg_id,reg_dtm,mod_id,mod_dtm,aply_exch_rate,reg_chnl,pc_mod_yn,reg_dt,seq_no,item_detl_use_yn,prjt_use_yn,trco_rppr_enm,doc_title,adv_paym_trns_seq,hand_doc_id,trco_type,gst_no,eml,inv_type,wht_cd,hand_reg_yn,einv_invoiceinfo,totl_dis_amt,einv_invoicestatus,einv_checkresults,einv_numericsymbol,einv_invoicesymbol,einv_title,einv_mccqt,einv_buyerbankacc,einv_sellerbankacc,einv_paymenttype,einv_listnumber,einv_listdate,einv_totalamtinletter,einv_buyersignby,einv_buyersigndate,einv_buyersigntime,einv_sellersignby,einv_sellersigndate,einv_sellersigntime,einv_qrcode,einv_buyerfullname,totl_fee_amt,einv_buyerbankname,einv_sellerbankname,einv_originalinvoice,dis_type,einv_con_doc_id,totl_bef_dis_amt,einv_invoicestatus_bef,einv_testresults,einv_rate,einv_buyercitizenid,disp_doc_id,over_due_days) VALUES
